(
  set -euo pipefail
  if [[ "$(uname -s)" != Linux || ! -r /proc/version ]]; then
    printf '%s\n' 'Run :pmi-auth in WSL.'
    exit 2
  fi
  case "$(</proc/version)" in
    *Microsoft*|*microsoft*|*WSL*|*wsl*) ;;
    *) printf '%s\n' 'The approved authentication store is in WSL.'; exit 2 ;;
  esac

  pmi_root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
  if [[ ! -f "$pmi_root/scripts/auth/ensure.mjs" ]]; then
    shopt -s nullglob
    pmi_roots=(/mnt/c/Users/*/Documents/github-windows/pmiKCkb_and_ownerRouter)
    if [[ ${#pmi_roots[@]} -ne 1 ]]; then
      printf '%s\n' 'Open the PMI repository in WSL, then run :pmi-auth again.'
      exit 2
    fi
    pmi_root="${pmi_roots[0]}"
  fi
  cd -- "$pmi_root"

  node --import tsx --input-type=module 3<&0 <<'PMI_AUTH'
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium } from "playwright-core";
import { ensureAuthenticated } from "./scripts/auth/ensure.mjs";
import { LOCAL_PRINCIPAL } from "./scripts/auth/identities.mjs";
import { resolveHarnessBrowser, validateProfilePath } from "./scripts/auth/browser.ts";
import { APPROVED_PREDECESSOR } from "./lib/production-assurance/predecessor-exception.mjs";
import {
  launchGuardedManagedBrowser,
  closeGuardedManagedBrowser,
} from "./lib/production-assurance/guarded-browser.ts";

const account = LOCAL_PRINCIPAL;
const origin = new URL(APPROVED_PREDECESSOR.canonicalOrigin).origin;
const profile = join(homedir(), "pmi-assurance", "owner-admin");
const readyStates = new Set(["ok", "repaired", "skipped"]);

class AuthStop extends Error {
  constructor(message, code = 2) {
    super(message);
    this.code = code;
  }
}
async function check(options) {
  const result = await ensureAuthenticated({ ...options, unattended: true });
  console.log(result.lines.join("\n"));
  return result;
}
function pending(result) {
  return result.items.filter((item) => !readyStates.has(item.state));
}
function requireReady(result) {
  if (result.exitCode !== 0) {
    throw new AuthStop("Authentication is not ready; review the condition above.", result.exitCode);
  }
}
function enroll(command, args) {
  const result = spawnSync(command, args, {
    stdio: [3, "inherit", "inherit"],
    env: args[0] === "auth" && args[1] === "login"
      ? { ...process.env, GH_PROMPT_DISABLED: "1" } : process.env,
  });
  if (result.error || result.status !== 0) {
    throw new AuthStop(
      "Enrollment did not finish; stopped without another login attempt.",
      result.status > 0 ? result.status : 1,
    );
  }
}
function capture(command, args) {
  return spawnSync(command, args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 60_000,
  });
}
function githubIdentity(command, expected) {
  const result = capture(command, ["api", "user", "--hostname", "github.com", "--jq", ".login"]);
  if (result.error || result.status !== 0) {
    throw new AuthStop("GitHub identity lookup failed; no login was attempted.");
  }
  if (result.stdout.trim().toLowerCase() !== expected.toLowerCase()) {
    throw new AuthStop("Unexpected GitHub identity; use the PMI repository owner's existing account.");
  }
}
function authenticateGithub() {
  const remote = capture("git", ["remote", "get-url", "origin"]);
  const match = remote.stdout?.trim().match(
    /^(?:https:\/\/github\.com\/|git@github\.com:)([^/]+)\/[^/]+$/,
  );
  if (remote.error || remote.status !== 0 || !match) {
    throw new AuthStop("The PMI origin remote must identify its approved GitHub owner.");
  }
  const candidates = ["gh", "/mnt/c/Program Files/GitHub CLI/gh.exe"];
  let command, status;
  for (const candidate of candidates) {
    if (candidate !== "gh" && !existsSync(candidate)) continue;
    const result = capture(candidate, ["auth", "status", "--hostname", "github.com"]);
    if (result.error?.code === "ENOENT") continue;
    command = candidate;
    status = result;
    break;
  }
  if (!command || status.error) throw new AuthStop("GitHub CLI is unavailable in WSL.");
  if (status.status !== 0) {
    const diagnostic = String(status.stdout ?? "") + String(status.stderr ?? "");
    const enrollmentNeeded = /not logged into (?:any GitHub hosts|github\.com)|token[^\n]* is invalid/i.test(diagnostic);
    if (process.env.GH_TOKEN?.trim() || process.env.GITHUB_TOKEN?.trim() || !enrollmentNeeded) {
      throw new AuthStop("GitHub authentication failed; inspect the existing token or reported condition.");
    }
    console.log("Complete GitHub's browser sign-in as the PMI repository owner.");
    enroll(command, ["auth", "login", "--hostname", "github.com", "--git-protocol", "https", "--web"]);
    const verified = capture(command, ["auth", "status", "--hostname", "github.com"]);
    if (verified.error || verified.status !== 0) {
      throw new AuthStop("GitHub enrollment was not verified; stopped without retrying.");
    }
  }
  githubIdentity(command, match[1]);
  console.log("GitHub authentication verified.");
}
async function verifyAppIdentity() {
  let mutations = 0;
  const context = await launchGuardedManagedBrowser({
    profile: validateProfilePath(profile),
    executablePath: resolveHarnessBrowser(),
    headless: true,
    viewport: { width: 1280, height: 900 },
    launchTimeoutMs: 60_000,
    launchPersistentContext: chromium.launchPersistentContext.bind(chromium),
    onMutationAttempt: () => { mutations += 1; },
  });
  try {
    const page = await context.newPage();
    await page.goto(origin + "/", { waitUntil: "domcontentloaded", timeout: 60_000 });
    const response = await context.request.get(origin + "/api/auth/session", {
      timeout: 60_000,
      maxRedirects: 0,
    });
    if (response.status() !== 204) {
      throw new AuthStop("The PMI application refused the browser session.");
    }
    // The app has verified this profile's session. Inspect only its identity claims in
    // memory; no cookie is exported, injected, logged, or copied to another store.
    const sessions = (await context.cookies(origin)).filter(
      (cookie) => cookie.name === "__session" && cookie.path === "/",
    );
    if (sessions.length !== 1) throw new AuthStop("The PMI session identity is unverified.");
    const claims = JSON.parse(Buffer.from(sessions[0].value.split(".")[1], "base64url").toString());
    const role = (await page.locator(".user-role").first().textContent({ timeout: 10_000 }))?.trim();
    if (claims.email !== account || claims.role !== "Admin" || role !== "Admin") {
      throw new AuthStop("Unexpected PMI application identity or role; enrollment was not retried.");
    }
    if (mutations !== 0) throw new AuthStop("PMI verification blocked an unexpected write.");
  } finally {
    await closeGuardedManagedBrowser(context);
  }
}

try {
  if (origin.startsWith("https://") === false) throw new AuthStop("The PMI origin must use HTTPS.");
  const override = Object.entries(process.env).some(([key, value]) =>
    (key === "GOOGLE_APPLICATION_CREDENTIALS" || key === "CLOUDSDK_CONFIG" ||
      key.startsWith("CLOUDSDK_AUTH_")) && value?.trim(),
  );
  if (override) throw new AuthStop("Unset Google credential, token, and store overrides before authentication.");

  console.log("1. Check the existing PMI provider configuration.");
  requireReady(await check({ need: ["env"] }));

  console.log("2. Obtain or reuse GitHub authentication.");
  authenticateGithub();

  console.log("3. Obtain or reuse the approved Google CLI/ADC credentials.");
  const hostOptions = { need: ["gcloud", "adc"] };
  let host = await check(hostOptions);
  if (host.exitCode !== 0) {
    const enrollmentCodes = new Set(["adc_missing", "principal_unknown", "stale_token", "adc_stale"]);
    const blocked = pending(host);
    if (!blocked.length || blocked.some((item) => !enrollmentCodes.has(item.code))) {
      requireReady(host);
    }
    enroll("npm", ["run", "auth:session", "--", "--browser"]);
    host = await check(hostOptions);
    requireReady(host);
  }

  console.log("4. Obtain or reuse the PMI application browser session.");
  const appOptions = {
    need: ["canary"],
    canary: [{ label: "admin", profile, origin, email: account }],
  };
  let app = existsSync(profile) ? await check(appOptions) : null;
  if (!app || app.exitCode !== 0) {
    if (app) {
      const blocked = pending(app);
      if (!blocked.length || blocked.some((item) => item.code !== "human_required")) {
        requireReady(app);
      }
    }
    enroll("npm", [
      "run", "auth:enroll-canary", "--",
      "--profile=" + profile, "--origin=" + origin, "--email=" + account,
    ]);
    app = await check(appOptions);
    requireReady(app);
  }
  await verifyAppIdentity();
  requireReady(await check({ need: ["gcloud", "adc", "env", "gh"] }));
  console.log("GitHub, Google CLI/ADC, provider configuration, and canonical PMI Admin authentication verified.");
} catch (error) {
  console.error(error instanceof AuthStop ? error.message :
    "Authentication stopped after an unexpected error; inspect the last reported condition before retrying.");
  process.exitCode = error instanceof AuthStop ? error.code : 1;
}
PMI_AUTH
)
